// === EXTRACTION & NORMALISATION DE LA RÉSERVATION ===
const agentOutput = $input.first().json;
const fullText = agentOutput.output || agentOutput.text || '';

let chatResponse = fullText;
let hasBooking = false;
let booking = null;
let bookingStartISO = null;
let bookingEndISO = null;

// 1. Extraire le bloc JSON entre ---BOOKING---
const match = fullText.match(/---BOOKING---([\s\S]*?)---BOOKING---/);
if (match) {
  chatResponse = fullText.split('---BOOKING---')[0].trim();
  try {
    const data = JSON.parse(match[1].trim());
    if (data.confirmed === true && data.type && data.date && data.time && data.name) {
      hasBooking = true;
      booking = data;

      // 2. Normaliser la date FR vers ISO
      const moisFR = {janvier:1,fevrier:2,février:2,mars:3,avril:4,mai:5,juin:6,juillet:7,aout:8,août:8,septembre:9,octobre:10,novembre:11,decembre:12,décembre:12};
      const joursFR = {lundi:1,mardi:2,mercredi:3,jeudi:4,vendredi:5,samedi:6,dimanche:0};

      let dateStr = String(data.date).toLowerCase().trim();
      let timeStr = String(data.time).toLowerCase().trim().replace('h',':').replace(/[^\d:]/g,'');
      if (!timeStr.includes(':')) timeStr = timeStr + ':00';
      if (timeStr.split(':')[1] === '') timeStr = timeStr + '00';
      const [hh, mm] = timeStr.split(':').map(Number);

      let target = null;

      // Format JJ/MM/AAAA
      const dmy = dateStr.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})/);
      // Format AAAA-MM-JJ
      const ymd = dateStr.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);
      // Format "15 mars" ou "15 mars 2026"
      const txt = dateStr.match(/(\d{1,2})\s+([a-zûéèà]+)(?:\s+(\d{4}))?/);
      // Format jour de semaine
      const dayName = Object.keys(joursFR).find(j => dateStr.includes(j));

      const now = new Date();

      if (ymd) {
        target = new Date(+ymd[1], +ymd[2]-1, +ymd[3], hh||9, mm||0);
      } else if (dmy) {
        let y = +dmy[3]; if (y < 100) y += 2000;
        target = new Date(y, +dmy[2]-1, +dmy[1], hh||9, mm||0);
      } else if (txt && moisFR[txt[2]]) {
        const y = txt[3] ? +txt[3] : now.getFullYear();
        target = new Date(y, moisFR[txt[2]]-1, +txt[1], hh||9, mm||0);
        if (!txt[3] && target < now) target.setFullYear(y+1);
      } else if (dayName) {
        const targetDow = joursFR[dayName];
        target = new Date(now);
        let diff = (targetDow - now.getDay() + 7) % 7;
        if (diff === 0) diff = 7;
        target.setDate(now.getDate() + diff);
        target.setHours(hh||9, mm||0, 0, 0);
      }

      if (target && !isNaN(target.getTime())) {
        bookingStartISO = target.toISOString();
        const end = new Date(target.getTime() + 60*60*1000);
        bookingEndISO = end.toISOString();
      }
    }
  } catch(e) {
    // JSON mal formé, on ignore le booking
  }
}

return [{
  json: {
    output: chatResponse,
    chatResponse,
    hasBooking,
    bookingStartISO,
    bookingEndISO,
    bookingType:  booking ? booking.type  : null,
    bookingDate:  booking ? booking.date  : null,
    bookingTime:  booking ? booking.time  : null,
    bookingName:  booking ? booking.name  : null,
    bookingPhone: booking ? booking.phone : null
  }
}];

