// Recherche fuzzy dans la FAQ
const query = ($('Sub-Workflow Trigger (FAQ Tool)').first().json.query || '').toLowerCase();
const rows = $input.all();

const norm = s => String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const q = norm(query);
const keywords = q.split(/\s+/).filter(w => w.length > 2);

const scored = rows.map(r => {
  const text = norm(`${r.json['Catégorie']||''} ${r.json['Question']||''} ${r.json['Réponse']||''}`);
  let score = 0;
  for (const k of keywords) if (text.includes(k)) score++;
  return { row: r.json, score };
}).filter(x => x.score > 0).sort((a,b) => b.score - a.score).slice(0, 5);

const results = scored.length > 0 ? scored.map(s => s.row) : rows.slice(0,5).map(r => r.json);

const formatted = results.map(r => `[${r['Catégorie']||''}] Q: ${r['Question']||''}\nR: ${r['Réponse']||''}`).join('\n\n');

return [{ json: { response: formatted || 'Aucun résultat dans la FAQ.' } }];
